def Q(S, lv, body, ok, bad, why, p=None):
    b.q(S, lv, body, options=[ok] + list(bad), answer=ok, why=why, passage=p)


def SH(S, lv, body, answers, why, p=None):
    b.q(S, lv, body, answers=answers, why=why, passage=p)


